mapper.select:
SELECT si.stock_in_no, si.create_time AS in_time, CASE si.type WHEN 1 THEN '采购' WHEN 2 THEN '调拨' WHEN 3 THEN '生产' WHEN 4 THEN '盘盈' WHEN 5 THEN '其他' WHEN 6 THEN '销售退货' WHEN 7 THEN '拒收退货' ELSE '未知' END AS type_name, si.source_bill_no, w.warehouse_name, s.supplier_name, sii.line_no, sii.sku_code, sii.sku_name, sii.spec_text, sii.unit_name, sii.expected_qty, sii.actual_qty, sii.cost_price, sii.subtotal, sii.batch_no, sii.location_code FROM wms_stock_in si LEFT JOIN wms_warehouse w ON si.warehouse_id = w.warehouse_id AND w.deleted = 0 LEFT JOIN wms_supplier s ON si.supplier_id = s.supplier_id AND s.deleted = 0 LEFT JOIN wms_stock_in_item sii ON si.stock_in_id = sii.stock_in_id WHERE si.deleted = 0
AND si.stock_in_no LIKE CONCAT('%', #{params.stockInNo}, '%')
AND si.warehouse_id = #{params.warehouseId}
AND si.create_time >= #{params.dateRangeStart}
AND si.create_time <= #{params.dateRangeEnd}
ORDER BY si.create_time DESC, sii.line_no ASC

SELECT so.stock_out_no, so.create_time AS out_time, CASE so.type WHEN 1 THEN '销售' WHEN 2 THEN '调拨' WHEN 3 THEN '生产' WHEN 4 THEN '损耗' WHEN 5 THEN '其他' ELSE '未知' END AS type_name, so.source_bill_no, w.warehouse_name, soi.line_no, soi.sku_code, soi.sku_name, soi.spec_text, soi.unit_name, soi.expected_qty, soi.actual_qty, soi.cost_price, soi.subtotal_cost, soi.sale_price, soi.subtotal_sale FROM wms_stock_out so LEFT JOIN wms_warehouse w ON so.warehouse_id = w.warehouse_id AND w.deleted = 0 LEFT JOIN wms_stock_out_item soi ON so.stock_out_id = soi.stock_out_id WHERE so.deleted = 0
AND so.stock_out_no LIKE CONCAT('%', #{params.stockOutNo}, '%')
AND so.warehouse_id = #{params.warehouseId}
AND so.create_time >= #{params.dateRangeStart}
AND so.create_time <= #{params.dateRangeEnd}
ORDER BY so.create_time DESC, soi.line_no ASC
